const aiResponse = $input.first().json;

// Get AI brief - supports both n8n AI node and raw API formats
let brief = '';
if (aiResponse.content && aiResponse.content[0] && aiResponse.content[0].text) {
  brief = aiResponse.content[0].text;
} else if (aiResponse.output) {
  brief = aiResponse.output;
} else if (aiResponse.text) {
  brief = aiResponse.text;
} else {
  brief = 'Sales brief unavailable.';
}

const auditData = $('Build Audit HTML').first().json;
const pdfBinary = $('Generate Audit PDF1').first().binary.auditPDF;

return [{
  json: {
    brief,
    name: auditData.name,
    email: auditData.email,
    brandName: auditData.brandName,
    role: auditData.role,
    unitCount: auditData.unitCount,
    phone: auditData.phone,
    linkedin: auditData.linkedin,
    survivalScore: auditData.survivalScore
  },
  binary: {
    auditPDF: pdfBinary
  }
}];
